-- 027_strength_template_languages.sql
-- The strength programs of the catalogue in French, English and German.
-- Each existing program becomes the version of the language it was written
-- in (six in English, eight in French) and keeps its content; the two other
-- languages are added. Users then only see the programs in their language.
--
-- A program an admin has renamed is not recognised: it stays visible in every
-- language, and its language can be set in Admin.
--
-- Needs 026 (the locale column). Safe to re-run. All-or-nothing.

BEGIN;

UPDATE program_templates SET locale = 'en'
WHERE locale IS NULL AND name IN ('Full Body — Beginner', 'Strength 5×5', 'Upper / Lower Split', 'Push / Pull / Legs', 'Lean & Strong', 'Home Dumbbell');

UPDATE program_templates SET locale = 'fr'
WHERE locale IS NULL AND name IN ('Essentiel 2 jours', 'Remise en forme', 'Force 3×5', 'Prise de masse 5 jours', 'Fessiers et jambes', 'Haltères 4 jours', 'Poids du corps', 'Sèche 4 jours');

-- French translations
INSERT INTO program_templates (name, description, goal, level, days_per_week, home_friendly, structure, is_published, sort_order, locale)
SELECT 'Full Body — Débutant', 'Trois séances complètes par semaine : la façon la plus simple et la plus efficace de commencer.', 'general', 'beginner', 3, false, '[{"name":"Jour A","exercises":[{"exerciseName":"Back Squat","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Barbell Bench Press","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Seated Cable Row","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Plank","targetSets":3,"targetReps":"30-45s","restSec":60}]},{"name":"Jour B","exercises":[{"exerciseName":"Romanian Deadlift","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Overhead Press","targetSets":3,"targetReps":"8-10","restSec":120},{"exerciseName":"Lat Pulldown","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Hanging Leg Raise","targetSets":3,"targetReps":"10-15","restSec":60}]},{"name":"Jour C","exercises":[{"exerciseName":"Leg Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Incline Dumbbell Press","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Dumbbell Row","targetSets":3,"targetReps":"10-12","restSec":90},{"exerciseName":"Cable Crunch","targetSets":3,"targetReps":"12-15","restSec":60}]}]'::jsonb, true, 0, 'fr'
WHERE NOT EXISTS (SELECT 1 FROM program_templates WHERE name = 'Full Body — Débutant' AND locale = 'fr');

